// Define a simple Matrix struct to hold the result
#[derive(Debug, Clone)]
pub struct Matrix<T> {
    data: Vec<Vec<T>>,
    rows: usize,
    cols: usize,
}

impl<T: Clone> Matrix<T> {
    // Helper to create a new matrix
    fn new(rows: usize, cols: usize) -> Self {
        Matrix {
            data: vec![vec![]; rows],
            rows,
            cols,
        }
    }
    
    // Helper to set all elements
    fn fill_with<F>(&mut self, mut f: F) 
    where
        F: FnMut(usize, usize) -> T,
    {
        for i in 0..self.rows {
            self.data[i] = (0..self.cols).map(|j| f(i, j)).collect();
        }
    }
}

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Validate inputs based on assumptions
    assert!(!a.is_empty(), "Array must have positive length");
    assert_eq!(shape.len(), 2, "Shape must have exactly 2 elements");
    
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    
    assert!(r > 0 && c > 0, "Both dimensions must be positive");
    
    let a_len = a.len();
    
    // Check that exactly one dimension matches array length
    let r_matches = r == a_len;
    let c_matches = c == a_len;
    
    assert!(
        r_matches ^ c_matches,  // XOR: exactly one must be true
        "Exactly one dimension must match array length"
    );
    
    let mut matrix = Matrix::new(r, c);
    
    if r_matches {
        // Column vector: array length matches rows
        // Each row i gets element a[i] repeated across all columns
        matrix.fill_with(|i, _| a[i]);
    } else {
        // Row vector: array length matches columns  
        // Each column j gets element a[j] repeated across all rows
        matrix.fill_with(|_, j| a[j]);
    }
    
    matrix
}